      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória temporária gerenciada no método Update() gerando quase 8 MB por frame. As causas principais são concatenação repetitiva de strings em loop (s += i.ToString()), que aloca centenas de objetos string imutáveis na heap, criação de arrays de objetos temporários não reutilizados e chamadas a GameObject.FindObjectsOfType<GameObject>(), que alocam novos arrays na memória gerenciada a cada iteração. Esse acúmulo frequente aciona o Garbage Collector com pausas de 24.57 ms, estourando a janela orçamentária do frame.",
      "codigo_refatorado": "using System;
using System.Text;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _sharedStringBuilder;
        private static MaterialPropertyBlock _sharedPropertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private readonly List<GameObject> _spawnedPool = new List<GameObject>();
        private Transform _cachedTransform;

        private void Awake()
        {
            _cachedTransform = transform;
            _sharedStringBuilder = new StringBuilder(gcConcatIterations * 4);
            if (_sharedPropertyBlock == null)
            {
                _sharedPropertyBlock = new MaterialPropertyBlock();
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i.ToString()));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var collider = quad.GetComponent<Collider>();
                if (collider != null) Destroy(collider);

                quad.name = string.Concat("Overdraw_", i.ToString());
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _sharedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sharedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int childCount = _cachedTransform.childCount;
                    for (int c = 0; c < childCount; c++)
                    {
                        var child = _cachedTransform.GetChild(c);
                        GC.KeepAlive(child);
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            Vector3 spawnPos = UnityEngine.Random.insideUnitSphere * spawnRadius;
            var clone = Instantiate(testPrefab, spawnPos, Quaternion.identity, _cachedTransform);
            _spawnedPool.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    _sharedPropertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_sharedPropertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, strings são imutáveis: toda vez que você faz 'texto += algo', a memória antiga é descartada e uma nova área de memória é criada na Heap. Ao fazer isso centenas de vezes todo frame, a memória fica cheia de lixo rapidamente. O Garbage Collector (GC) precisa parar o jogo por vários milissegundos para limpar essa bagunça, causando travamentos visíveis (micro-stutters). A solução é usar StringBuilder para manipulação de textos e evitar chamar funções como 'FindObjectsOfType' dentro do Update, pois elas alocam novos arrays e realizam buscas pesadas continuamente. Além disso, usar 'renderer.material' instancia uma cópia do material na GPU, enquanto 'MaterialPropertyBlock' altera as propriedades visuais sem alocar novos materiais ou quebrar instanciamento."
    }
  ],
  "dicas_level_design": null
}

